CREATE TABLE IF NOT EXISTS seasons (year INTEGER PRIMARY KEY NOT NULL, game_key TEXT NOT NULL, schema_version INTEGER NOT NULL, field_definition TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS organization_settings (organization_id TEXT PRIMARY KEY NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, invite_code_hash TEXT, invite_code_salt TEXT, invite_code_encrypted TEXT, invite_code_iv TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY NOT NULL, count INTEGER NOT NULL, last_request INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_verifications (provider TEXT PRIMARY KEY NOT NULL, verification_code TEXT NOT NULL, received_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_delivery_status (provider TEXT PRIMARY KEY NOT NULL, last_received_at INTEGER NOT NULL, status TEXT NOT NULL, message_type TEXT);
CREATE TABLE IF NOT EXISTS relay_devices (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, public_key_jwk TEXT NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER, revoked_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_relay_devices_user ON relay_devices (organization_id, user_id);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), season_year INTEGER NOT NULL REFERENCES seasons(year), tba_event_key TEXT NOT NULL, name TEXT NOT NULL, is_current INTEGER DEFAULT 0 NOT NULL, tba_etag TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_events_org_tba ON events (organization_id, tba_event_key);
CREATE INDEX IF NOT EXISTS idx_events_current ON events (organization_id, is_current);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), tba_match_key TEXT NOT NULL, comp_level TEXT NOT NULL, match_number INTEGER NOT NULL, scheduled_at INTEGER, predicted_at INTEGER, alliances TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_org_tba ON matches (organization_id, tba_match_key);
CREATE INDEX IF NOT EXISTS idx_matches_event_order ON matches (event_id, comp_level, match_number);
CREATE TABLE IF NOT EXISTS scout_entries (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), match_id TEXT NOT NULL REFERENCES matches(id), team_number INTEGER NOT NULL, scout_user_id TEXT NOT NULL REFERENCES users(id), station TEXT NOT NULL, season_year INTEGER NOT NULL REFERENCES seasons(year), schema_version INTEGER NOT NULL, payload TEXT NOT NULL, client_updated_at INTEGER NOT NULL, sync_version INTEGER DEFAULT 1 NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_entries_assignment ON scout_entries (organization_id, match_id, team_number, scout_user_id);
CREATE INDEX IF NOT EXISTS idx_entries_analysis ON scout_entries (organization_id, event_id, team_number);
CREATE TABLE IF NOT EXISTS entry_audit (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entry_id TEXT NOT NULL REFERENCES scout_entries(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_entry_audit_org_time ON entry_audit (organization_id, created_at);
CREATE TABLE IF NOT EXISTS scout_assignments (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), match_id TEXT NOT NULL REFERENCES matches(id), team_number INTEGER NOT NULL, scout_user_id TEXT NOT NULL REFERENCES users(id), station TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_assignment_station ON scout_assignments (organization_id, match_id, station);
CREATE INDEX IF NOT EXISTS idx_assignment_scout ON scout_assignments (scout_user_id, event_id);
CREATE TABLE IF NOT EXISTS pit_entries (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), team_number INTEGER NOT NULL, scout_user_id TEXT NOT NULL REFERENCES users(id), season_year INTEGER NOT NULL REFERENCES seasons(year), drivetrain TEXT, swerve_module TEXT, motor_types TEXT, weight_lbs INTEGER, dimensions TEXT, payload TEXT NOT NULL, photo_object_key TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_pit_team_event ON pit_entries (organization_id, event_id, team_number);
CREATE TABLE IF NOT EXISTS match_plans (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), match_id TEXT NOT NULL REFERENCES matches(id), author_user_id TEXT NOT NULL REFERENCES users(id), plan TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_plans_match ON match_plans (organization_id, match_id);
CREATE TABLE IF NOT EXISTS pick_lists (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), owner_user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, is_official INTEGER DEFAULT 0 NOT NULL, rankings TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_picklists_event ON pick_lists (organization_id, event_id);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), event_id TEXT NOT NULL REFERENCES events(id), match_id TEXT REFERENCES matches(id), team_number INTEGER, uploader_user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_media_match ON media (organization_id, match_id);
